/* Sentence gym rewrites, merged into EH_QUIZ so the mistake book can show them. */
window.EH_QUIZ=Object.assign(window.EH_QUIZ||{},{"gym:neg-inversion:1": {"id": "gym:neg-inversion:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "I have never seen a queue this long at the passport office. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Never</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Never 开头。</span></span>", "answer": "Never have I seen a queue this long at the passport office. / Never before have I seen a queue this long at the passport office.", "explain": "<span class=\"enx\">Never + have + I: the auxiliary jumps in front of the subject, as in a question.</span><span class=\"zh\" lang=\"zh-Hans\">Never 提前后，助动词 have 跳到主语 I 前面，语序像疑问句。</span>"}, "gym:neg-inversion:2": {"id": "gym:neg-inversion:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "We rarely get a straight answer from the call centre. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Rarely</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Rarely 开头。</span></span>", "answer": "Rarely do we get a straight answer from the call centre. / Rarely do we get a straight answer from the call center.", "explain": "<span class=\"enx\">There is no auxiliary in \"we get\", so add do: Rarely do we get.</span><span class=\"zh\" lang=\"zh-Hans\">原句 we get 没有助动词，倒装要补 do：Rarely do we get。</span>"}, "gym:neg-inversion:3": {"id": "gym:neg-inversion:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "The landlord not only raised the rent, but he also cut the heating hours. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Not only</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Not only 开头。</span></span>", "answer": "Not only did the landlord raise the rent, but he also cut the heating hours. / Not only did the landlord raise the rent, he also cut the heating hours. / Not only did the landlord raise the rent, but he cut the heating hours as well.", "explain": "<span class=\"enx\">Past simple raised becomes did ... raise; only the first half inverts.</span><span class=\"zh\" lang=\"zh-Hans\">过去式 raised 变成 did ... raise；只有前半句倒装，后半句照常。</span>"}, "gym:neg-inversion:4": {"id": "gym:neg-inversion:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "She had just sat down when the fire alarm went off. <span class=\"muted\">→ <span class=\"enx\">Use <i>No sooner ... than</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 No sooner ... than。</span></span>", "answer": "No sooner had she sat down than the fire alarm went off.", "explain": "<span class=\"enx\">No sooner pairs with than, not when, and takes the past perfect: had she sat.</span><span class=\"zh\" lang=\"zh-Hans\">No sooner 配 than，不配 when，后面用过去完成时：had she sat。</span>"}, "gym:neg-inversion:5": {"id": "gym:neg-inversion:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "You should not leave a child alone in a car under any circumstances. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Under no circumstances</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Under no circumstances 开头。</span></span>", "answer": "Under no circumstances should you leave a child alone in a car. / Under no circumstances should a child be left alone in a car.", "explain": "<span class=\"enx\">The negative moves to the front, so the not in the plain sentence disappears.</span><span class=\"zh\" lang=\"zh-Hans\">否定词已经在句首，原句里的 not 要去掉。</span>"}, "gym:neg-inversion:6": {"id": "gym:neg-inversion:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "We only realised how much the move had cost when the first bills arrived. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Only when</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Only when 开头。</span></span>", "answer": "Only when the first bills arrived did we realise how much the move had cost. / Only when the first bills arrived did we realize how much the move had cost.", "explain": "<span class=\"enx\">With only when, the inversion comes in the main clause, after the time clause: did we realise.</span><span class=\"zh\" lang=\"zh-Hans\">Only when 的倒装发生在主句里，时间从句之后：did we realise。</span>"}, "gym:neg-inversion:7": {"id": "gym:neg-inversion:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "They had no idea that the road would be closed for a month. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Little</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Little 开头。</span></span>", "answer": "Little did they know that the road would be closed for a month. / Little did they know the road would be closed for a month.", "explain": "<span class=\"enx\">Little did they know is a fixed way to say they had no idea, often before a twist.</span><span class=\"zh\" lang=\"zh-Hans\">Little did they know 是「他们万万没想到」的固定说法，常放在转折之前。</span>"}, "gym:neg-inversion:8": {"id": "gym:neg-inversion:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "The manager did not apologise once during the meeting. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Not once</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Not once 开头。</span></span>", "answer": "Not once did the manager apologise during the meeting. / Not once did the manager apologize during the meeting.", "explain": "<span class=\"enx\">Not once did + subject + base verb; the did not of the plain sentence goes.</span><span class=\"zh\" lang=\"zh-Hans\">Not once did + 主语 + 动词原形；原句的 did not 去掉。</span>"}, "gym:neg-inversion:9": {"id": "gym:neg-inversion:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "You will not find cheaper fresh fish anywhere in the city. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Nowhere</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Nowhere 开头。</span></span>", "answer": "Nowhere in the city will you find cheaper fresh fish. / Nowhere will you find cheaper fresh fish in the city.", "explain": "<span class=\"enx\">Nowhere replaces not ... anywhere, then will jumps before you.</span><span class=\"zh\" lang=\"zh-Hans\">Nowhere 取代 not ... anywhere，然后 will 跳到 you 前面。</span>"}, "gym:neg-inversion:10": {"id": "gym:neg-inversion:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "He seldom takes a day off, even when he is ill. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Seldom</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Seldom 开头。</span></span>", "answer": "Seldom does he take a day off, even when he is ill.", "explain": "<span class=\"enx\">Third person present: does he take, and takes loses its -s.</span><span class=\"zh\" lang=\"zh-Hans\">第三人称现在时：does he take，takes 去掉 -s。</span>"}, "gym:neg-inversion:11": {"id": "gym:neg-inversion:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "The clinic didn&#x27;t call us back until the next week. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Not until</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Not until 开头。</span></span>", "answer": "Not until the next week did the clinic call us back.", "explain": "<span class=\"enx\">Not until + time, then did + subject + verb.</span><span class=\"zh\" lang=\"zh-Hans\">Not until + 时间，接 did + 主语 + 动词。</span>"}, "gym:neg-inversion:12": {"id": "gym:neg-inversion:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "The applicants were not told at any point that the form had changed. <span class=\"muted\">→ <span class=\"enx\">Start with <i>At no point</i> (or <i>At no time</i>).</span><span class=\"zh\" lang=\"zh-Hans\">以 At no point（或 At no time）开头。</span></span>", "answer": "At no point were the applicants told that the form had changed. / At no time were the applicants told that the form had changed.", "explain": "<span class=\"enx\">The passive keeps were as the auxiliary: were the applicants told.</span><span class=\"zh\" lang=\"zh-Hans\">被动句的助动词就是 were：were the applicants told。</span>"}, "gym:neg-inversion:13": {"id": "gym:neg-inversion:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "We had hardly unpacked when the neighbours came to say hello. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Hardly</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Hardly 开头。</span></span>", "answer": "Hardly had we unpacked when the neighbours came to say hello. / Hardly had we unpacked when the neighbors came to say hello.", "explain": "<span class=\"enx\">Hardly pairs with when (No sooner pairs with than).</span><span class=\"zh\" lang=\"zh-Hans\">Hardly 配 when（No sooner 才配 than）。</span>"}, "gym:neg-inversion:14": {"id": "gym:neg-inversion:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "You can only renew the permit online if you have the original number. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Only if</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Only if 开头。</span></span>", "answer": "Only if you have the original number can you renew the permit online.", "explain": "<span class=\"enx\">The condition comes first; the main clause inverts: can you renew.</span><span class=\"zh\" lang=\"zh-Hans\">条件先说，主句倒装：can you renew。</span>"}, "gym:neg-inversion:15": {"id": "gym:neg-inversion:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Inversion after negative adverbs", "q": "The bank did not explain the fee, and it did not apologise either. <span class=\"muted\">→ <span class=\"enx\">Join the two halves with <i>nor</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 nor 连接两半。</span></span>", "answer": "The bank did not explain the fee, nor did it apologise. / The bank did not explain the fee, nor did it apologize.", "explain": "<span class=\"enx\">After nor the auxiliary comes first, and either disappears.</span><span class=\"zh\" lang=\"zh-Hans\">nor 后面助动词提前，either 去掉。</span>"}, "gym:inverted-conditionals:1": {"id": "gym:inverted-conditionals:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If I had known about the strike, I would have taken the bus. <span class=\"muted\">→ <span class=\"enx\">Drop <i>if</i>; start with <i>Had</i>.</span><span class=\"zh\" lang=\"zh-Hans\">去掉 if，以 Had 开头。</span></span>", "answer": "Had I known about the strike, I would have taken the bus.", "explain": "<span class=\"enx\">If I had known → Had I known: had moves to the front and if disappears.</span><span class=\"zh\" lang=\"zh-Hans\">If I had known → Had I known：had 提前，if 去掉。</span>"}, "gym:inverted-conditionals:2": {"id": "gym:inverted-conditionals:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If you need any help with the form, call the front desk. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Should</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Should 开头。</span></span>", "answer": "Should you need any help with the form, call the front desk. / Should you need any help with the form, please call the front desk.", "explain": "<span class=\"enx\">Should + subject + base verb: need, not needs or needed.</span><span class=\"zh\" lang=\"zh-Hans\">Should + 主语 + 动词原形：need，不是 needs 或 needed。</span>"}, "gym:inverted-conditionals:3": {"id": "gym:inverted-conditionals:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If I were in your position, I would ask for the decision in writing. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Were</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Were 开头。</span></span>", "answer": "Were I in your position, I would ask for the decision in writing.", "explain": "<span class=\"enx\">Were I works only with were, never with was: Was I in your position is wrong.</span><span class=\"zh\" lang=\"zh-Hans\">只能用 were 倒装，不能用 was：Was I in your position 是错的。</span>"}, "gym:inverted-conditionals:4": {"id": "gym:inverted-conditionals:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If the city were to raise parking fees, many small shops would suffer. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Were</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Were 开头。</span></span>", "answer": "Were the city to raise parking fees, many small shops would suffer.", "explain": "<span class=\"enx\">Were + subject + to + verb is the formal way to float an unlikely future.</span><span class=\"zh\" lang=\"zh-Hans\">Were + 主语 + to + 动词，是正式地提出一个不太可能的将来。</span>"}, "gym:inverted-conditionals:5": {"id": "gym:inverted-conditionals:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If we had left ten minutes earlier, we would have caught the ferry. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Had</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Had 开头。</span></span>", "answer": "Had we left ten minutes earlier, we would have caught the ferry.", "explain": "<span class=\"enx\">Third conditional: Had we left ..., we would have caught.</span><span class=\"zh\" lang=\"zh-Hans\">第三类条件句：Had we left ..., we would have caught。</span>"}, "gym:inverted-conditionals:6": {"id": "gym:inverted-conditionals:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If anyone asks where I am, tell them I&#x27;m at the clinic. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Should</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Should 开头。</span></span>", "answer": "Should anyone ask where I am, tell them I'm at the clinic.", "explain": "<span class=\"enx\">asks becomes ask after should.</span><span class=\"zh\" lang=\"zh-Hans\">should 之后 asks 变 ask。</span>"}, "gym:inverted-conditionals:7": {"id": "gym:inverted-conditionals:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If she had not checked the receipt, she would never have noticed the double charge. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Had</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Had 开头。</span></span>", "answer": "Had she not checked the receipt, she would never have noticed the double charge.", "explain": "<span class=\"enx\">Negative: Had she not checked. Hadn't she checked is not used in this pattern.</span><span class=\"zh\" lang=\"zh-Hans\">否定写成 Had she not checked；这个句式不用 Hadn't she。</span>"}, "gym:inverted-conditionals:8": {"id": "gym:inverted-conditionals:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If the parcel does not arrive by Friday, contact the seller. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Should</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Should 开头。</span></span>", "answer": "Should the parcel not arrive by Friday, contact the seller.", "explain": "<span class=\"enx\">Should the parcel not arrive: not goes after the subject.</span><span class=\"zh\" lang=\"zh-Hans\">Should the parcel not arrive：not 放在主语之后。</span>"}, "gym:inverted-conditionals:9": {"id": "gym:inverted-conditionals:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If they were to offer you the night shift, would you take it? <span class=\"muted\">→ <span class=\"enx\">Start with <i>Were</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Were 开头。</span></span>", "answer": "Were they to offer you the night shift, would you take it?", "explain": "<span class=\"enx\">Were they to offer = if they offered, in a more careful voice.</span><span class=\"zh\" lang=\"zh-Hans\">Were they to offer 就是 if they offered，语气更斟酌。</span>"}, "gym:inverted-conditionals:10": {"id": "gym:inverted-conditionals:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If there had been a sign, nobody would have parked there. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Had</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Had 开头。</span></span>", "answer": "Had there been a sign, nobody would have parked there.", "explain": "<span class=\"enx\">there behaves like a subject: Had there been.</span><span class=\"zh\" lang=\"zh-Hans\">there 当主语用：Had there been。</span>"}, "gym:inverted-conditionals:11": {"id": "gym:inverted-conditionals:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If you have any questions about your results, your doctor can explain them. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Should</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Should 开头。</span></span>", "answer": "Should you have any questions about your results, your doctor can explain them.", "explain": "<span class=\"enx\">A standard line in letters from offices and clinics.</span><span class=\"zh\" lang=\"zh-Hans\">机构和诊所来信里的标准句。</span>"}, "gym:inverted-conditionals:12": {"id": "gym:inverted-conditionals:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "I would have called you if I had had your number. <span class=\"muted\">→ <span class=\"enx\">Put the condition at the end without <i>if</i>.</span><span class=\"zh\" lang=\"zh-Hans\">条件放句末，去掉 if。</span></span>", "answer": "I would have called you had I had your number. / Had I had your number, I would have called you.", "explain": "<span class=\"enx\">had I had looks odd but is correct: the first had is the auxiliary, the second is the main verb.</span><span class=\"zh\" lang=\"zh-Hans\">had I had 看着怪但没错：第一个 had 是助动词，第二个是实义动词。</span>"}, "gym:inverted-conditionals:13": {"id": "gym:inverted-conditionals:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If it were not for the night bus, I could not get to work. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Were it not for</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Were it not for 开头。</span></span>", "answer": "Were it not for the night bus, I could not get to work.", "explain": "<span class=\"enx\">Were it not for + noun = without this thing, now.</span><span class=\"zh\" lang=\"zh-Hans\">Were it not for + 名词＝要不是有这个（现在）。</span>"}, "gym:inverted-conditionals:14": {"id": "gym:inverted-conditionals:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If it had not been for my neighbour, we would have missed the flight. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Had it not been for</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Had it not been for 开头。</span></span>", "answer": "Had it not been for my neighbour, we would have missed the flight. / Had it not been for my neighbor, we would have missed the flight.", "explain": "<span class=\"enx\">Had it not been for + noun = without this person or thing, in the past.</span><span class=\"zh\" lang=\"zh-Hans\">Had it not been for + 名词＝要不是有这个人或这件事（过去）。</span>"}, "gym:inverted-conditionals:15": {"id": "gym:inverted-conditionals:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Conditionals without if: Had I known, Should you need, Were it not for", "q": "If the weather turns bad, the outdoor class will move to the gym. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Should</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Should 开头。</span></span>", "answer": "Should the weather turn bad, the outdoor class will move to the gym.", "explain": "<span class=\"enx\">turns becomes turn after should.</span><span class=\"zh\" lang=\"zh-Hans\">should 之后 turns 变 turn。</span>"}, "gym:it-cleft:1": {"id": "gym:it-cleft:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "The night shift changed my sleep, not the long commute. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>the night shift</i> with <i>It was ... that</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 It was ... that 突出 the night shift。</span></span>", "answer": "It was the night shift that changed my sleep, not the long commute. / It was the night shift, not the long commute, that changed my sleep.", "explain": "<span class=\"enx\">It was + focus + that + the rest of the sentence.</span><span class=\"zh\" lang=\"zh-Hans\">It was + 焦点 + that + 句子其余部分。</span>"}, "gym:it-cleft:2": {"id": "gym:it-cleft:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "My sister found the mistake in the tax slip. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>my sister</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 my sister。</span></span>", "answer": "It was my sister who found the mistake in the tax slip. / It was my sister that found the mistake in the tax slip.", "explain": "<span class=\"enx\">For a person, who is more usual than that; both are correct.</span><span class=\"zh\" lang=\"zh-Hans\">焦点是人时 who 比 that 常见，两个都对。</span>"}, "gym:it-cleft:3": {"id": "gym:it-cleft:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "We only understood the rules when we read the letter a second time. <span class=\"muted\">→ <span class=\"enx\">Focus on the time with <i>It was only when ... that</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 It was only when ... that 突出时间。</span></span>", "answer": "It was only when we read the letter a second time that we understood the rules.", "explain": "<span class=\"enx\">The only moves into the cleft: It was only when.</span><span class=\"zh\" lang=\"zh-Hans\">only 移进分裂结构：It was only when。</span>"}, "gym:it-cleft:4": {"id": "gym:it-cleft:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "The price worries me, not the quality. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>the price</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 the price。</span></span>", "answer": "It is the price that worries me, not the quality. / It is the price, not the quality, that worries me.", "explain": "<span class=\"enx\">The contrast can sit at the end or inside commas.</span><span class=\"zh\" lang=\"zh-Hans\">对比的部分可以放句末，也可以用逗号夹在中间。</span>"}, "gym:it-cleft:5": {"id": "gym:it-cleft:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "I didn&#x27;t feel at home until I joined the choir. <span class=\"muted\">→ <span class=\"enx\">Use <i>It was not until ... that</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 It was not until ... that。</span></span>", "answer": "It was not until I joined the choir that I felt at home.", "explain": "<span class=\"enx\">The negative moves into the cleft, so the main verb becomes positive: felt.</span><span class=\"zh\" lang=\"zh-Hans\">否定移进分裂结构，主句动词变肯定：felt。</span>"}, "gym:it-cleft:6": {"id": "gym:it-cleft:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "You need a booking number at this counter, not a passport. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>a booking number</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 a booking number。</span></span>", "answer": "It is a booking number that you need at this counter, not a passport. / It is a booking number, not a passport, that you need at this counter.", "explain": "<span class=\"enx\">Useful at a counter when someone keeps showing the wrong document.</span><span class=\"zh\" lang=\"zh-Hans\">在窗口前对方一直拿错证件时很好用。</span>"}, "gym:it-cleft:7": {"id": "gym:it-cleft:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "Housing costs pushed us out of the city. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>housing costs</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 housing costs。</span></span>", "answer": "It was housing costs that pushed us out of the city.", "explain": "<span class=\"enx\">Even with a plural focus, keep It was: It was housing costs.</span><span class=\"zh\" lang=\"zh-Hans\">焦点是复数也照样用 It was：It was housing costs。</span>"}, "gym:it-cleft:8": {"id": "gym:it-cleft:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "The doctor, not the nurse, makes the final decision. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>the doctor</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 the doctor。</span></span>", "answer": "It is the doctor, not the nurse, who makes the final decision. / It is the doctor who makes the final decision, not the nurse. / It is the doctor, not the nurse, that makes the final decision.", "explain": "<span class=\"enx\">The verb after who agrees with the focus: the doctor ... makes.</span><span class=\"zh\" lang=\"zh-Hans\">who 之后的动词跟焦点一致：the doctor ... makes。</span>"}, "gym:it-cleft:9": {"id": "gym:it-cleft:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "People remember the tone of an email, not the exact words. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>the tone of an email</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 the tone of an email。</span></span>", "answer": "It is the tone of an email that people remember, not the exact words. / It is the tone of an email, not the exact words, that people remember.", "explain": "<span class=\"enx\">The object can be the focus too; that then introduces the rest.</span><span class=\"zh\" lang=\"zh-Hans\">宾语也可以做焦点，that 引出其余部分。</span>"}, "gym:it-cleft:10": {"id": "gym:it-cleft:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "I lost my temper because of the waiting. <span class=\"muted\">→ <span class=\"enx\">Focus on the reason.</span><span class=\"zh\" lang=\"zh-Hans\">突出原因。</span></span>", "answer": "It was because of the waiting that I lost my temper. / It was the waiting that made me lose my temper.", "explain": "<span class=\"enx\">A reason phrase can go into the cleft: It was because of ... that.</span><span class=\"zh\" lang=\"zh-Hans\">原因短语也能放进去：It was because of ... that。</span>"}, "gym:it-cleft:11": {"id": "gym:it-cleft:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "The heat pump saved us money last winter, not the new windows. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>the heat pump</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 the heat pump。</span></span>", "answer": "It was the heat pump that saved us money last winter, not the new windows. / It was the heat pump, not the new windows, that saved us money last winter.", "explain": "<span class=\"enx\">Past event, so It was.</span><span class=\"zh\" lang=\"zh-Hans\">过去的事，用 It was。</span>"}, "gym:it-cleft:12": {"id": "gym:it-cleft:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "In the second year, things began to get easier. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>in the second year</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 in the second year。</span></span>", "answer": "It was in the second year that things began to get easier.", "explain": "<span class=\"enx\">A time phrase in the cleft takes that, never when: It was in the second year that.</span><span class=\"zh\" lang=\"zh-Hans\">时间短语放进分裂句后接 that，不接 when。</span>"}, "gym:it-cleft:13": {"id": "gym:it-cleft:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "A neighbour told us about the community garden. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>a neighbour</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 a neighbour。</span></span>", "answer": "It was a neighbour who told us about the community garden. / It was a neighbour that told us about the community garden. / It was a neighbor who told us about the community garden. / It was a neighbor that told us about the community garden.", "explain": "<span class=\"enx\">The answer to \"how did you hear about it?\"</span><span class=\"zh\" lang=\"zh-Hans\">回答「你怎么知道的？」。</span>"}, "gym:it-cleft:14": {"id": "gym:it-cleft:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "We chose this school for its music classes. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>its music classes</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 its music classes。</span></span>", "answer": "It was for its music classes that we chose this school. / It was the music classes that made us choose this school.", "explain": "<span class=\"enx\">Keep the preposition with the focus: It was for its music classes that.</span><span class=\"zh\" lang=\"zh-Hans\">介词跟焦点一起走：It was for its music classes that。</span>"}, "gym:it-cleft:15": {"id": "gym:it-cleft:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · It-cleft: It was the price that...", "q": "Small habits, not big plans, change your health. <span class=\"muted\">→ <span class=\"enx\">Focus on <i>small habits</i>.</span><span class=\"zh\" lang=\"zh-Hans\">突出 small habits。</span></span>", "answer": "It is small habits, not big plans, that change your health. / It is small habits that change your health, not big plans.", "explain": "<span class=\"enx\">A general truth, so It is.</span><span class=\"zh\" lang=\"zh-Hans\">一般道理，用 It is。</span>"}, "gym:what-cleft:1": {"id": "gym:what-cleft:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "We need a clear timetable. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What we need</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What we need 开头。</span></span>", "answer": "What we need is a clear timetable.", "explain": "<span class=\"enx\">What + clause + is + the new information.</span><span class=\"zh\" lang=\"zh-Hans\">What + 从句 + is + 新信息。</span>"}, "gym:what-cleft:2": {"id": "gym:what-cleft:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "I miss the food from home most. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What I miss most</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What I miss most 开头。</span></span>", "answer": "What I miss most is the food from home. / What I miss most about home is the food.", "explain": "<span class=\"enx\">The verb after what goes into the first half; the thing you miss comes last.</span><span class=\"zh\" lang=\"zh-Hans\">动词放进前半句，想念的东西放最后。</span>"}, "gym:what-cleft:3": {"id": "gym:what-cleft:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "The delay annoyed me, not the cost. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What annoyed me</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What annoyed me 开头。</span></span>", "answer": "What annoyed me was the delay, not the cost. / What annoyed me was not the cost but the delay.", "explain": "<span class=\"enx\">Past feeling, so was.</span><span class=\"zh\" lang=\"zh-Hans\">过去的感受，用 was。</span>"}, "gym:what-cleft:4": {"id": "gym:what-cleft:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "Then the power went out. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What happened</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What happened 开头。</span></span>", "answer": "What happened next was that the power went out. / What happened then was that the power went out. / What happened was that the power went out.", "explain": "<span class=\"enx\">What happened was that + full clause: a common way to start telling a story.</span><span class=\"zh\" lang=\"zh-Hans\">What happened was that + 完整从句：讲故事时常用的开头。</span>"}, "gym:what-cleft:5": {"id": "gym:what-cleft:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "You should keep every receipt. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What you should do</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What you should do 开头。</span></span>", "answer": "What you should do is keep every receipt. / What you should do is to keep every receipt.", "explain": "<span class=\"enx\">After What ... do is, the bare verb is most natural; to is also correct.</span><span class=\"zh\" lang=\"zh-Hans\">What ... do is 之后用动词原形最自然，加 to 也对。</span>"}, "gym:what-cleft:6": {"id": "gym:what-cleft:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "She only wanted a straight answer. <span class=\"muted\">→ <span class=\"enx\">Start with <i>All she wanted</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 All she wanted 开头。</span></span>", "answer": "All she wanted was a straight answer.", "explain": "<span class=\"enx\">All = the only thing; it makes the request sound small and reasonable.</span><span class=\"zh\" lang=\"zh-Hans\">All＝唯一的东西，让要求显得小而合理。</span>"}, "gym:what-cleft:7": {"id": "gym:what-cleft:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "Regular sleep helps most with stress. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What helps most</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What helps most 开头。</span></span>", "answer": "What helps most with stress is regular sleep. / What helps most is regular sleep.", "explain": "<span class=\"enx\">The subject regular sleep moves to the end, where the stress falls.</span><span class=\"zh\" lang=\"zh-Hans\">主语 regular sleep 挪到句末重音的位置。</span>"}, "gym:what-cleft:8": {"id": "gym:what-cleft:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "I didn&#x27;t expect the friendliness of strangers. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What I didn't expect</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What I didn't expect 开头。</span></span>", "answer": "What I didn't expect was the friendliness of strangers.", "explain": "<span class=\"enx\">The negative stays in the what-clause.</span><span class=\"zh\" lang=\"zh-Hans\">否定留在 what 从句里。</span>"}, "gym:what-cleft:9": {"id": "gym:what-cleft:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "They changed the bus route without telling anyone. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What they did</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What they did 开头。</span></span>", "answer": "What they did was change the bus route without telling anyone. / What they did was to change the bus route without telling anyone.", "explain": "<span class=\"enx\">What ... did was + bare verb: change, not changed.</span><span class=\"zh\" lang=\"zh-Hans\">What ... did was + 动词原形：change，不是 changed。</span>"}, "gym:what-cleft:10": {"id": "gym:what-cleft:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "We just called the insurer, nothing more. <span class=\"muted\">→ <span class=\"enx\">Start with <i>All we did</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 All we did 开头。</span></span>", "answer": "All we did was call the insurer. / All we did was to call the insurer.", "explain": "<span class=\"enx\">All we did was + bare verb, often to answer \"what did you do wrong?\".</span><span class=\"zh\" lang=\"zh-Hans\">All we did was + 动词原形，常用来回答「你们到底做了什么」。</span>"}, "gym:what-cleft:11": {"id": "gym:what-cleft:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "Employers look for reliability above all. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What employers look for</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What employers look for 开头。</span></span>", "answer": "What employers look for above all is reliability. / What employers look for is reliability above all.", "explain": "<span class=\"enx\">Keep the preposition for inside the what-clause.</span><span class=\"zh\" lang=\"zh-Hans\">介词 for 留在 what 从句里。</span>"}, "gym:what-cleft:12": {"id": "gym:what-cleft:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "The long waiting list frustrates patients. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What frustrates patients</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What frustrates patients 开头。</span></span>", "answer": "What frustrates patients is the long waiting list.", "explain": "<span class=\"enx\">frustrates stays singular: what counts as one thing.</span><span class=\"zh\" lang=\"zh-Hans\">frustrates 用单数：what 算一件事。</span>"}, "gym:what-cleft:13": {"id": "gym:what-cleft:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "I&#x27;d like to know why the fee went up. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What I'd like to know</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What I'd like to know 开头。</span></span>", "answer": "What I'd like to know is why the fee went up. / What I would like to know is why the fee went up.", "explain": "<span class=\"enx\">A polite but firm way to ask a question in a meeting or on the phone.</span><span class=\"zh\" lang=\"zh-Hans\">开会或打电话时客气而坚定的提问方式。</span>"}, "gym:what-cleft:14": {"id": "gym:what-cleft:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "Patience, not talent, gets you through a new language. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What gets you through</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What gets you through 开头。</span></span>", "answer": "What gets you through a new language is patience, not talent.", "explain": "<span class=\"enx\">The contrast lands at the very end.</span><span class=\"zh\" lang=\"zh-Hans\">对比落在句子最末。</span>"}, "gym:what-cleft:15": {"id": "gym:what-cleft:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · What-cleft: What we need is...", "q": "The children enjoyed the snow most. <span class=\"muted\">→ <span class=\"enx\">Start with <i>What the children enjoyed most</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 What the children enjoyed most 开头。</span></span>", "answer": "What the children enjoyed most was the snow.", "explain": "<span class=\"enx\">The snow becomes the answer at the end.</span><span class=\"zh\" lang=\"zh-Hans\">the snow 成了句末的答案。</span>"}, "gym:participle-clauses:1": {"id": "gym:participle-clauses:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "After she had finished her shift, she drove straight to the school. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Having</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Having 开头。</span></span>", "answer": "Having finished her shift, she drove straight to the school.", "explain": "<span class=\"enx\">Having + past participle: the first action is complete before the second.</span><span class=\"zh\" lang=\"zh-Hans\">Having + 过去分词：第一个动作在第二个之前完成。</span>"}, "gym:participle-clauses:2": {"id": "gym:participle-clauses:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "Because I didn&#x27;t know the area, I booked a hotel near the station. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Not knowing</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Not knowing 开头。</span></span>", "answer": "Not knowing the area, I booked a hotel near the station.", "explain": "<span class=\"enx\">not goes before the participle: Not knowing, not Knowing not.</span><span class=\"zh\" lang=\"zh-Hans\">not 放在分词前：Not knowing，不是 Knowing not。</span>"}, "gym:participle-clauses:3": {"id": "gym:participle-clauses:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "Because he felt tired after the flight, he went to bed at seven. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Feeling</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Feeling 开头。</span></span>", "answer": "Feeling tired after the flight, he went to bed at seven.", "explain": "<span class=\"enx\">A present participle for a state that explains the action.</span><span class=\"zh\" lang=\"zh-Hans\">现在分词表示解释行为的状态。</span>"}, "gym:participle-clauses:4": {"id": "gym:participle-clauses:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "When they were faced with a rent increase, the tenants formed a group. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Faced with</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Faced with 开头。</span></span>", "answer": "Faced with a rent increase, the tenants formed a group.", "explain": "<span class=\"enx\">Past participle, because the tenants were faced with it (passive meaning).</span><span class=\"zh\" lang=\"zh-Hans\">用过去分词，因为租户是「面对」的承受者（被动意义）。</span>"}, "gym:participle-clauses:5": {"id": "gym:participle-clauses:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "The library was built in 1912, and it is the oldest building on the street. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Built</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Built 开头。</span></span>", "answer": "Built in 1912, the library is the oldest building on the street.", "explain": "<span class=\"enx\">The library is the subject of both parts, so the past participle works.</span><span class=\"zh\" lang=\"zh-Hans\">两部分的主语都是图书馆，所以能用过去分词。</span>"}, "gym:participle-clauses:6": {"id": "gym:participle-clauses:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "The storm knocked out power across the region and left thousands without heat. <span class=\"muted\">→ <span class=\"enx\">End with an <i>-ing</i> clause for the result.</span><span class=\"zh\" lang=\"zh-Hans\">用句末的 -ing 从句表示结果。</span></span>", "answer": "The storm knocked out power across the region, leaving thousands without heat.", "explain": "<span class=\"enx\">A comma, then leaving: the second event follows from the first.</span><span class=\"zh\" lang=\"zh-Hans\">逗号加 leaving：第二件事由第一件引起。</span>"}, "gym:participle-clauses:7": {"id": "gym:participle-clauses:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "Since we have lived here for ten years, we know which roads flood. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Having lived</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Having lived 开头。</span></span>", "answer": "Having lived here for ten years, we know which roads flood.", "explain": "<span class=\"enx\">Having + past participle can give the background that explains what you know.</span><span class=\"zh\" lang=\"zh-Hans\">Having + 过去分词可以交代「为什么知道」的背景。</span>"}, "gym:participle-clauses:8": {"id": "gym:participle-clauses:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "As she was worried about the cost, she asked for a written quote. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Worried</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Worried 开头。</span></span>", "answer": "Worried about the cost, she asked for a written quote.", "explain": "<span class=\"enx\">Drop as she was; the adjective-like participle does the work.</span><span class=\"zh\" lang=\"zh-Hans\">去掉 as she was，形容词性的分词就够了。</span>"}, "gym:participle-clauses:9": {"id": "gym:participle-clauses:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "I was walking home when I noticed the shop had closed. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Walking home</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Walking home 开头。</span></span>", "answer": "Walking home, I noticed the shop had closed.", "explain": "<span class=\"enx\">The subject I is the one walking, so the clause is safe.</span><span class=\"zh\" lang=\"zh-Hans\">走路的人就是 I，所以这个从句没问题。</span>"}, "gym:participle-clauses:10": {"id": "gym:participle-clauses:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "The form was written in plain language, so it was easy to fill in. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Written</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Written 开头。</span></span>", "answer": "Written in plain language, the form was easy to fill in.", "explain": "<span class=\"enx\">The participle gives the reason; so disappears.</span><span class=\"zh\" lang=\"zh-Hans\">分词交代原因，so 就不用了。</span>"}, "gym:participle-clauses:11": {"id": "gym:participle-clauses:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "While I was waiting for the bus, I listened to a podcast. <span class=\"muted\">→ <span class=\"enx\">Keep <i>While</i> and drop <i>I was</i>.</span><span class=\"zh\" lang=\"zh-Hans\">保留 While，去掉 I was。</span></span>", "answer": "While waiting for the bus, I listened to a podcast. / Waiting for the bus, I listened to a podcast.", "explain": "<span class=\"enx\">While + -ing keeps the time meaning clear.</span><span class=\"zh\" lang=\"zh-Hans\">While + -ing 让「同时」的意思更清楚。</span>"}, "gym:participle-clauses:12": {"id": "gym:participle-clauses:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "After he moved to Calgary, he started cycling to work. <span class=\"muted\">→ <span class=\"enx\">Use <i>After</i> + <i>-ing</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 After + -ing。</span></span>", "answer": "After moving to Calgary, he started cycling to work. / Having moved to Calgary, he started cycling to work.", "explain": "<span class=\"enx\">After moving and Having moved both work; after moving is less formal.</span><span class=\"zh\" lang=\"zh-Hans\">After moving 和 Having moved 都对；after moving 没那么正式。</span>"}, "gym:participle-clauses:13": {"id": "gym:participle-clauses:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "When he was asked why he quit, he said the hours were too long. <span class=\"muted\">→ <span class=\"enx\">Use <i>When asked</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 When asked。</span></span>", "answer": "When asked why he quit, he said the hours were too long. / Asked why he quit, he said the hours were too long.", "explain": "<span class=\"enx\">When asked is common in news reports and interviews.</span><span class=\"zh\" lang=\"zh-Hans\">When asked 在新闻和采访里很常见。</span>"}, "gym:participle-clauses:14": {"id": "gym:participle-clauses:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "Because she had been told the office was closed, she went home. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Having been told</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Having been told 开头。</span></span>", "answer": "Having been told the office was closed, she went home.", "explain": "<span class=\"enx\">Having been + past participle: passive and earlier.</span><span class=\"zh\" lang=\"zh-Hans\">Having been + 过去分词：被动，而且更早。</span>"}, "gym:participle-clauses:15": {"id": "gym:participle-clauses:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Participle clauses: Having finished..., Not knowing..., Built in...", "q": "The new rules came into force in March and changed how renters apply. <span class=\"muted\">→ <span class=\"enx\">End with an <i>-ing</i> clause.</span><span class=\"zh\" lang=\"zh-Hans\">用句末的 -ing 从句。</span></span>", "answer": "The new rules came into force in March, changing how renters apply.", "explain": "<span class=\"enx\">The -ing clause tells the reader what the change means in practice.</span><span class=\"zh\" lang=\"zh-Hans\">-ing 从句告诉读者这个变化实际意味着什么。</span>"}, "gym:reduced-relatives:1": {"id": "gym:reduced-relatives:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "People who live near the airport hear planes all night. <span class=\"muted\">→ <span class=\"enx\">Cut the relative clause to an <i>-ing</i> phrase.</span><span class=\"zh\" lang=\"zh-Hans\">把定语从句缩成 -ing 短语。</span></span>", "answer": "People living near the airport hear planes all night.", "explain": "<span class=\"enx\">Active and ongoing: who live → living.</span><span class=\"zh\" lang=\"zh-Hans\">主动、持续：who live → living。</span>"}, "gym:reduced-relatives:2": {"id": "gym:reduced-relatives:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "The letter that was sent last week had the wrong address. <span class=\"muted\">→ <span class=\"enx\">Cut <i>that was</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 that was。</span></span>", "answer": "The letter sent last week had the wrong address.", "explain": "<span class=\"enx\">Passive: that was sent → sent.</span><span class=\"zh\" lang=\"zh-Hans\">被动：that was sent → sent。</span>"}, "gym:reduced-relatives:3": {"id": "gym:reduced-relatives:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Anyone who is interested in the course should sign up by Friday. <span class=\"muted\">→ <span class=\"enx\">Cut <i>who is</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 who is。</span></span>", "answer": "Anyone interested in the course should sign up by Friday.", "explain": "<span class=\"enx\">An adjective phrase can follow the noun directly.</span><span class=\"zh\" lang=\"zh-Hans\">形容词短语可以直接跟在名词后面。</span>"}, "gym:reduced-relatives:4": {"id": "gym:reduced-relatives:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "She was the first person who noticed the leak. <span class=\"muted\">→ <span class=\"enx\">Use <i>the first ... to</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 the first ... to。</span></span>", "answer": "She was the first person to notice the leak. / She was the first to notice the leak.", "explain": "<span class=\"enx\">After first, last and only, use to + verb.</span><span class=\"zh\" lang=\"zh-Hans\">first、last、only 之后用 to + 动词。</span>"}, "gym:reduced-relatives:5": {"id": "gym:reduced-relatives:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Drivers who park on this street need a permit. <span class=\"muted\">→ <span class=\"enx\">Cut to an <i>-ing</i> phrase.</span><span class=\"zh\" lang=\"zh-Hans\">缩成 -ing 短语。</span></span>", "answer": "Drivers parking on this street need a permit.", "explain": "<span class=\"enx\">A rule for whoever does it, so -ing works.</span><span class=\"zh\" lang=\"zh-Hans\">规定适用于「正在这样做的人」，用 -ing 合适。</span>"}, "gym:reduced-relatives:6": {"id": "gym:reduced-relatives:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "The photos that were taken at the wedding are on the shared drive. <span class=\"muted\">→ <span class=\"enx\">Cut <i>that were</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 that were。</span></span>", "answer": "The photos taken at the wedding are on the shared drive.", "explain": "<span class=\"enx\">taken stays; only that were goes.</span><span class=\"zh\" lang=\"zh-Hans\">taken 保留，只删 that were。</span>"}, "gym:reduced-relatives:7": {"id": "gym:reduced-relatives:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Students who are waiting for their results cannot change courses. <span class=\"muted\">→ <span class=\"enx\">Cut <i>who are</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 who are。</span></span>", "answer": "Students waiting for their results cannot change courses.", "explain": "<span class=\"enx\">who are waiting → waiting.</span><span class=\"zh\" lang=\"zh-Hans\">who are waiting 省成 waiting。</span>"}, "gym:reduced-relatives:8": {"id": "gym:reduced-relatives:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Anything that is left in the staff fridge is thrown out on Fridays. <span class=\"muted\">→ <span class=\"enx\">Cut <i>that is</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 that is。</span></span>", "answer": "Anything left in the staff fridge is thrown out on Fridays.", "explain": "<span class=\"enx\">The usual wording of a notice on a shared fridge.</span><span class=\"zh\" lang=\"zh-Hans\">公用冰箱上告示的常见写法。</span>"}, "gym:reduced-relatives:9": {"id": "gym:reduced-relatives:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Families who are new to the area can join a free tour. <span class=\"muted\">→ <span class=\"enx\">Cut <i>who are</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 who are。</span></span>", "answer": "Families new to the area can join a free tour.", "explain": "<span class=\"enx\">new to the area follows the noun like a short label.</span><span class=\"zh\" lang=\"zh-Hans\">new to the area 像一个短标签跟在名词后。</span>"}, "gym:reduced-relatives:10": {"id": "gym:reduced-relatives:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Is there anyone who can drive me to the clinic? <span class=\"muted\">→ <span class=\"enx\">Use <i>anyone able to</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 anyone able to。</span></span>", "answer": "Is there anyone able to drive me to the clinic?", "explain": "<span class=\"enx\">who can → able to, a little more formal.</span><span class=\"zh\" lang=\"zh-Hans\">who can → able to，稍正式。</span>"}, "gym:reduced-relatives:11": {"id": "gym:reduced-relatives:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "The man who is sitting next to the window is my landlord. <span class=\"muted\">→ <span class=\"enx\">Cut <i>who is</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 who is。</span></span>", "answer": "The man sitting next to the window is my landlord.", "explain": "<span class=\"enx\">who is sitting → sitting.</span><span class=\"zh\" lang=\"zh-Hans\">who is sitting 省成 sitting。</span>"}, "gym:reduced-relatives:12": {"id": "gym:reduced-relatives:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Most of the money that was raised at the fair went to the food bank. <span class=\"muted\">→ <span class=\"enx\">Cut <i>that was</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 that was。</span></span>", "answer": "Most of the money raised at the fair went to the food bank.", "explain": "<span class=\"enx\">raised at the fair now sits right after money.</span><span class=\"zh\" lang=\"zh-Hans\">raised at the fair 紧跟在 money 后面。</span>"}, "gym:reduced-relatives:13": {"id": "gym:reduced-relatives:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Patients who live outside the city can ask for a video appointment. <span class=\"muted\">→ <span class=\"enx\">Cut to an <i>-ing</i> phrase.</span><span class=\"zh\" lang=\"zh-Hans\">缩成 -ing 短语。</span></span>", "answer": "Patients living outside the city can ask for a video appointment.", "explain": "<span class=\"enx\">A lasting situation, so living is natural.</span><span class=\"zh\" lang=\"zh-Hans\">持续的状况，用 living 自然。</span>"}, "gym:reduced-relatives:14": {"id": "gym:reduced-relatives:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "The only thing that is missing is your signature. <span class=\"muted\">→ <span class=\"enx\">Cut <i>that is</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 that is。</span></span>", "answer": "The only thing missing is your signature.", "explain": "<span class=\"enx\">Common on forms and in office emails.</span><span class=\"zh\" lang=\"zh-Hans\">表格和办公邮件里常见。</span>"}, "gym:reduced-relatives:15": {"id": "gym:reduced-relatives:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Reduced relative clauses: people living near..., the letter sent last week", "q": "Tenants who were affected by the flood will get a rent reduction. <span class=\"muted\">→ <span class=\"enx\">Cut <i>who were</i>.</span><span class=\"zh\" lang=\"zh-Hans\">删掉 who were。</span></span>", "answer": "Tenants affected by the flood will get a rent reduction.", "explain": "<span class=\"enx\">Passive: who were affected → affected.</span><span class=\"zh\" lang=\"zh-Hans\">被动：who were affected → affected。</span>"}, "gym:nominalisation:1": {"id": "gym:nominalisation:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "Because the office closed, we lost a week of work. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The closure of</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 The closure of 开头。</span></span>", "answer": "The closure of the office cost us a week of work. / The closure of the office meant we lost a week of work. / The closure of the office led to the loss of a week of work.", "explain": "<span class=\"enx\">close → closure; the event is now the subject, so you need a new verb such as cost.</span><span class=\"zh\" lang=\"zh-Hans\">close → closure；事件成了主语，需要一个新动词，比如 cost。</span>"}, "gym:nominalisation:2": {"id": "gym:nominalisation:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "Prices rose sharply, and many families changed how they shop. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The sharp rise in</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 The sharp rise in 开头。</span></span>", "answer": "The sharp rise in prices changed how many families shop. / A sharp rise in prices changed how many families shop. / The sharp rise in prices has changed how many families shop.", "explain": "<span class=\"enx\">The adverb sharply becomes the adjective sharp.</span><span class=\"zh\" lang=\"zh-Hans\">副词 sharply 变成形容词 sharp。</span>"}, "gym:nominalisation:3": {"id": "gym:nominalisation:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "The council decided to close the pool, and residents were angry. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The council's decision</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 The council's decision 开头。</span></span>", "answer": "The council's decision to close the pool angered residents. / The council's decision to close the pool made residents angry.", "explain": "<span class=\"enx\">decide → decision to; angry becomes the verb anger.</span><span class=\"zh\" lang=\"zh-Hans\">decide → decision to；angry 变成动词 anger。</span>"}, "gym:nominalisation:4": {"id": "gym:nominalisation:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "If you do not reply by the deadline, your file may be closed. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Failure to reply</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Failure to reply 开头。</span></span>", "answer": "Failure to reply by the deadline may result in the closure of your file. / Failure to reply by the deadline may lead to the closure of your file. / Failure to reply by the deadline may mean the closure of your file.", "explain": "<span class=\"enx\">You will see this pattern in official letters; recognising it matters more than writing it.</span><span class=\"zh\" lang=\"zh-Hans\">官方来信里常见这种句式；看懂它比会写更要紧。</span>"}, "gym:nominalisation:5": {"id": "gym:nominalisation:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "The bus was late, so the whole class missed the opening. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The late arrival of</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 The late arrival of 开头。</span></span>", "answer": "The late arrival of the bus meant the whole class missed the opening. / The late arrival of the bus made the whole class miss the opening.", "explain": "<span class=\"enx\">was late → late arrival; the bus moves into an of-phrase.</span><span class=\"zh\" lang=\"zh-Hans\">was late → late arrival；the bus 进了 of 短语。</span>"}, "gym:nominalisation:6": {"id": "gym:nominalisation:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "Fewer people are using cash, which worries some small shops. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The decline in</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 The decline in 开头。</span></span>", "answer": "The decline in cash use worries some small shops. / The decline in the use of cash worries some small shops.", "explain": "<span class=\"enx\">Fewer people are using → the decline in ... use.</span><span class=\"zh\" lang=\"zh-Hans\">Fewer people are using 变成 the decline in ... use。</span>"}, "gym:nominalisation:7": {"id": "gym:nominalisation:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "She was very patient with new staff, and everyone noticed. <span class=\"muted\">→ <span class=\"enx\">End with <i>her patience with</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 her patience with 结尾。</span></span>", "answer": "Everyone noticed her patience with new staff.", "explain": "<span class=\"enx\">patient → patience; the adjective becomes the thing noticed.</span><span class=\"zh\" lang=\"zh-Hans\">patient → patience；形容词变成被注意到的东西。</span>"}, "gym:nominalisation:8": {"id": "gym:nominalisation:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "Because the rules changed, many applicants had to start again. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The change in</i> (or <i>to</i>).</span><span class=\"zh\" lang=\"zh-Hans\">以 The change in（或 to）开头。</span></span>", "answer": "The change in the rules forced many applicants to start again. / The change to the rules forced many applicants to start again. / The change in the rules meant many applicants had to start again. / The change to the rules meant many applicants had to start again.", "explain": "<span class=\"enx\">change in and change to are both used for rules.</span><span class=\"zh\" lang=\"zh-Hans\">规则的变化用 change in 和 change to 都可以。</span>"}, "gym:nominalisation:9": {"id": "gym:nominalisation:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "When people know their rights, they are less afraid of the landlord. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Knowledge of</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Knowledge of 开头。</span></span>", "answer": "Knowledge of their rights makes people less afraid of the landlord.", "explain": "<span class=\"enx\">know → knowledge of; the noun has no article here.</span><span class=\"zh\" lang=\"zh-Hans\">know → knowledge of；这里不加冠词。</span>"}, "gym:nominalisation:10": {"id": "gym:nominalisation:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "The clinic is close to the station, which makes it easy to reach. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The clinic's closeness to</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 The clinic's closeness to 开头。</span></span>", "answer": "The clinic's closeness to the station makes it easy to reach. / The closeness of the clinic to the station makes it easy to reach.", "explain": "<span class=\"enx\">close (near) → closeness; do not confuse it with closure.</span><span class=\"zh\" lang=\"zh-Hans\">close（近）→ closeness，别和 closure（关闭）混。</span>"}, "gym:nominalisation:11": {"id": "gym:nominalisation:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "The company did not explain why it was cancelling the service. <span class=\"muted\">→ <span class=\"enx\">Use <i>no explanation for the cancellation of</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 no explanation for the cancellation of。</span></span>", "answer": "The company gave no explanation for the cancellation of the service. / The company offered no explanation for the cancellation of the service.", "explain": "<span class=\"enx\">Two nominalisations: explain → explanation, cancel → cancellation.</span><span class=\"zh\" lang=\"zh-Hans\">两处名词化：explain → explanation，cancel → cancellation。</span>"}, "gym:nominalisation:12": {"id": "gym:nominalisation:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "If you are exposed to loud noise for a long time, your hearing can suffer. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Long exposure to</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Long exposure to 开头。</span></span>", "answer": "Long exposure to loud noise can damage your hearing. / Long exposure to loud noise can harm your hearing. / Prolonged exposure to loud noise can damage your hearing.", "explain": "<span class=\"enx\">be exposed to → exposure to; a typical health-advice sentence.</span><span class=\"zh\" lang=\"zh-Hans\">be exposed to → exposure to，健康提示里的典型句子。</span>"}, "gym:nominalisation:13": {"id": "gym:nominalisation:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "Many people trust the news less than they used to. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Trust in the news</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Trust in the news 开头。</span></span>", "answer": "Trust in the news has fallen. / Public trust in the news has fallen. / Trust in the news has declined.", "explain": "<span class=\"enx\">trust as a noun takes in: trust in the news.</span><span class=\"zh\" lang=\"zh-Hans\">名词 trust 搭配 in：trust in the news。</span>"}, "gym:nominalisation:14": {"id": "gym:nominalisation:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "When the new manager arrived, the mood in the office changed. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The arrival of</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 The arrival of 开头。</span></span>", "answer": "The arrival of the new manager changed the mood in the office.", "explain": "<span class=\"enx\">arrive → arrival; the time clause becomes the cause.</span><span class=\"zh\" lang=\"zh-Hans\">arrive → arrival；时间从句变成了原因。</span>"}, "gym:nominalisation:15": {"id": "gym:nominalisation:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Nominalisation: from clause to noun phrase", "q": "The tenants refused to pay the increase, and the landlord went to the tribunal. <span class=\"muted\">→ <span class=\"enx\">Start with <i>The tenants' refusal</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 The tenants' refusal 开头。</span></span>", "answer": "The tenants' refusal to pay the increase led the landlord to go to the tribunal. / The tenants' refusal to pay the increase sent the landlord to the tribunal.", "explain": "<span class=\"enx\">refuse to → refusal to; the apostrophe goes after the s for plural tenants.</span><span class=\"zh\" lang=\"zh-Hans\">refuse to → refusal to；复数 tenants 的所有格撇号放在 s 后。</span>"}, "gym:fronting:1": {"id": "gym:fronting:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "I can accept the delay, but I cannot accept the rudeness. <span class=\"muted\">→ <span class=\"enx\">Put <i>the delay</i> and <i>the rudeness</i> first.</span><span class=\"zh\" lang=\"zh-Hans\">把 the delay 和 the rudeness 提到前面。</span></span>", "answer": "The delay I can accept, but the rudeness I cannot.", "explain": "<span class=\"enx\">Object first, then subject and verb, and no inversion: The delay I can accept.</span><span class=\"zh\" lang=\"zh-Hans\">宾语在前，主谓照常、不倒装：The delay I can accept。</span>"}, "gym:fronting:2": {"id": "gym:fronting:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "I never liked the winter driving, but I learned to live with it. <span class=\"muted\">→ <span class=\"enx\">Put <i>the winter driving</i> first.</span><span class=\"zh\" lang=\"zh-Hans\">把 the winter driving 提到前面。</span></span>", "answer": "The winter driving I never liked, but I learned to live with it.", "explain": "<span class=\"enx\">Fronting the object contrasts it with what you did come to accept.</span><span class=\"zh\" lang=\"zh-Hans\">宾语提前，与「后来接受了」形成对比。</span>"}, "gym:fronting:3": {"id": "gym:fronting:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "A small wooden church stands at the end of the road. <span class=\"muted\">→ <span class=\"enx\">Start with <i>At the end of the road</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 At the end of the road 开头。</span></span>", "answer": "At the end of the road stands a small wooden church.", "explain": "<span class=\"enx\">Place first, then verb, then the subject: stands a small wooden church.</span><span class=\"zh\" lang=\"zh-Hans\">先地点，再动词，最后主语：stands a small wooden church。</span>"}, "gym:fronting:4": {"id": "gym:fronting:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "The bus came round the corner at last. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Round the corner</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Round the corner 开头。</span></span>", "answer": "Round the corner came the bus at last. / At last round the corner came the bus.", "explain": "<span class=\"enx\">With a noun subject, came goes before it: came the bus.</span><span class=\"zh\" lang=\"zh-Hans\">主语是名词时 came 放在它前面：came the bus。</span>"}, "gym:fronting:5": {"id": "gym:fronting:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "The demand for the free clinic was so high that the doors opened an hour early. <span class=\"muted\">→ <span class=\"enx\">Start with <i>So high</i> (or <i>Such</i>).</span><span class=\"zh\" lang=\"zh-Hans\">以 So high（或 Such）开头。</span></span>", "answer": "So high was the demand for the free clinic that the doors opened an hour early. / Such was the demand for the free clinic that the doors opened an hour early.", "explain": "<span class=\"enx\">So + adjective + be + subject + that; Such was + subject + that.</span><span class=\"zh\" lang=\"zh-Hans\">So + 形容词 + be + 主语 + that；Such was + 主语 + that。</span>"}, "gym:fronting:6": {"id": "gym:fronting:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "The days of paper tickets are gone. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Gone</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Gone 开头。</span></span>", "answer": "Gone are the days of paper tickets.", "explain": "<span class=\"enx\">A fixed, slightly nostalgic pattern: Gone are the days of ...</span><span class=\"zh\" lang=\"zh-Hans\">固定句式，略带怀旧：Gone are the days of ...</span>"}, "gym:fronting:7": {"id": "gym:fronting:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "We could fix most of the problems ourselves. <span class=\"muted\">→ <span class=\"enx\">Put <i>most of the problems</i> first.</span><span class=\"zh\" lang=\"zh-Hans\">把 most of the problems 提到前面。</span></span>", "answer": "Most of the problems we could fix ourselves.", "explain": "<span class=\"enx\">Often followed by the part you could not do: ... the rest we left to a plumber.</span><span class=\"zh\" lang=\"zh-Hans\">后面常接做不到的部分：... the rest we left to a plumber。</span>"}, "gym:fronting:8": {"id": "gym:fronting:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "A note from the landlord was on the kitchen table. <span class=\"muted\">→ <span class=\"enx\">Start with <i>On the kitchen table</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 On the kitchen table 开头。</span></span>", "answer": "On the kitchen table was a note from the landlord.", "explain": "<span class=\"enx\">be also inverts after a place: was a note.</span><span class=\"zh\" lang=\"zh-Hans\">地点之后 be 也倒装：was a note。</span>"}, "gym:fronting:9": {"id": "gym:fronting:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "The results were more surprising than anything else. <span class=\"muted\">→ <span class=\"enx\">Start with <i>More surprising than anything else</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 More surprising than anything else 开头。</span></span>", "answer": "More surprising than anything else were the results.", "explain": "<span class=\"enx\">A comparative description first, then be and the subject.</span><span class=\"zh\" lang=\"zh-Hans\">比较级描述在前，接 be 和主语。</span>"}, "gym:fronting:10": {"id": "gym:fronting:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "Her family lived above the shop. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Above the shop</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Above the shop 开头。</span></span>", "answer": "Above the shop lived her family.", "explain": "<span class=\"enx\">A storyteller's order; fine in a family history, odd in an email.</span><span class=\"zh\" lang=\"zh-Hans\">讲故事的语序；写家族史可以，写邮件就怪。</span>"}, "gym:fronting:11": {"id": "gym:fronting:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "I don&#x27;t mind the long hours; I mind the short notice. <span class=\"muted\">→ <span class=\"enx\">Put <i>the long hours</i> and <i>the short notice</i> first.</span><span class=\"zh\" lang=\"zh-Hans\">把 the long hours 和 the short notice 提到前面。</span></span>", "answer": "The long hours I don't mind; the short notice I do.", "explain": "<span class=\"enx\">The second half can shrink to the short notice I do.</span><span class=\"zh\" lang=\"zh-Hans\">后半句可以缩成 the short notice I do。</span>"}, "gym:fronting:12": {"id": "gym:fronting:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "The weather was dreadful, and the food was even worse. <span class=\"muted\">→ <span class=\"enx\">Put <i>even worse</i> before the food.</span><span class=\"zh\" lang=\"zh-Hans\">把 even worse 放到 the food 前面。</span></span>", "answer": "The weather was dreadful; even worse was the food. / The weather was dreadful, and even worse was the food.", "explain": "<span class=\"enx\">even worse was the food builds up to the last complaint.</span><span class=\"zh\" lang=\"zh-Hans\">even worse was the food 把抱怨推到最高处。</span>"}, "gym:fronting:13": {"id": "gym:fronting:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "Two old armchairs sat in the corner of the waiting room. <span class=\"muted\">→ <span class=\"enx\">Start with <i>In the corner of the waiting room</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 In the corner of the waiting room 开头。</span></span>", "answer": "In the corner of the waiting room sat two old armchairs.", "explain": "<span class=\"enx\">sat two old armchairs: verb before the noun subject.</span><span class=\"zh\" lang=\"zh-Hans\">sat two old armchairs：动词在名词主语前。</span>"}, "gym:fronting:14": {"id": "gym:fronting:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "You can keep the old sofa; we are taking the table with us. <span class=\"muted\">→ <span class=\"enx\">Put <i>the old sofa</i> and <i>the table</i> first.</span><span class=\"zh\" lang=\"zh-Hans\">把 the old sofa 和 the table 提到前面。</span></span>", "answer": "The old sofa you can keep; the table we are taking with us.", "explain": "<span class=\"enx\">Each half opens with the thing being compared.</span><span class=\"zh\" lang=\"zh-Hans\">两半各以被比较的东西开头。</span>"}, "gym:fronting:15": {"id": "gym:fronting:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Fronting: The delay I can accept...", "q": "The rain came down just as the parade started. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Down</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Down 开头。</span></span>", "answer": "Down came the rain just as the parade started.", "explain": "<span class=\"enx\">Down came the rain is vivid; with a pronoun it would be Down it came.</span><span class=\"zh\" lang=\"zh-Hans\">Down came the rain 很生动；换成代词就是 Down it came。</span>"}, "gym:concession:1": {"id": "gym:concession:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Although I like the city, I can&#x27;t afford to live there. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Much as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Much as 开头。</span></span>", "answer": "Much as I like the city, I can't afford to live there.", "explain": "<span class=\"enx\">Much as + a verb of feeling (like, want, respect): softens what comes next.</span><span class=\"zh\" lang=\"zh-Hans\">Much as + 表示感情的动词（like、want、respect），让后面的话更柔和。</span>"}, "gym:concession:2": {"id": "gym:concession:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "It doesn&#x27;t matter how much you save; the rent keeps rising. <span class=\"muted\">→ <span class=\"enx\">Start with <i>However much</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 However much 开头。</span></span>", "answer": "However much you save, the rent keeps rising. / No matter how much you save, the rent keeps rising.", "explain": "<span class=\"enx\">However much + subject + verb, then the main clause; no but.</span><span class=\"zh\" lang=\"zh-Hans\">However much + 主谓，接主句，不加 but。</span>"}, "gym:concession:3": {"id": "gym:concession:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Although the plan seems strange, it works. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Strange as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Strange as 开头。</span></span>", "answer": "Strange as it may seem, the plan works. / Strange as the plan may seem, it works.", "explain": "<span class=\"enx\">Strange as it may seem is a fixed phrase for an odd but true point.</span><span class=\"zh\" lang=\"zh-Hans\">Strange as it may seem 是固定说法，引出一个怪但属实的点。</span>"}, "gym:concession:4": {"id": "gym:concession:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Although she was tired, she finished the report. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Tired as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Tired as 开头。</span></span>", "answer": "Tired as she was, she finished the report.", "explain": "<span class=\"enx\">Adjective + as + subject + be.</span><span class=\"zh\" lang=\"zh-Hans\">形容词 + as + 主语 + be。</span>"}, "gym:concession:5": {"id": "gym:concession:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "It does not matter how hard I try; I cannot remember his name. <span class=\"muted\">→ <span class=\"enx\">Start with <i>However hard</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 However hard 开头。</span></span>", "answer": "However hard I try, I cannot remember his name. / No matter how hard I try, I cannot remember his name.", "explain": "<span class=\"enx\">However + adverb works the same way as however much.</span><span class=\"zh\" lang=\"zh-Hans\">However + 副词，用法同 however much。</span>"}, "gym:concession:6": {"id": "gym:concession:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Although we wanted to help, we had no spare room. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Much as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Much as 开头。</span></span>", "answer": "Much as we wanted to help, we had no spare room.", "explain": "<span class=\"enx\">A gentle way to say no and show you care.</span><span class=\"zh\" lang=\"zh-Hans\">委婉拒绝、同时表明在乎的说法。</span>"}, "gym:concession:7": {"id": "gym:concession:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "You can decide anything you like, but tell us by Friday. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Whatever</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Whatever 开头。</span></span>", "answer": "Whatever you decide, tell us by Friday.", "explain": "<span class=\"enx\">Whatever = it does not matter what.</span><span class=\"zh\" lang=\"zh-Hans\">Whatever＝不管什么。</span>"}, "gym:concession:8": {"id": "gym:concession:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Although the course was expensive, it was worth every cent. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Expensive as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Expensive as 开头。</span></span>", "answer": "Expensive as the course was, it was worth every cent. / Expensive as it was, the course was worth every cent.", "explain": "<span class=\"enx\">The noun can sit in either half.</span><span class=\"zh\" lang=\"zh-Hans\">名词放前半句或后半句都行。</span>"}, "gym:concession:9": {"id": "gym:concession:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "It doesn&#x27;t matter how often you call; the line is always busy. <span class=\"muted\">→ <span class=\"enx\">Start with <i>However often</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 However often 开头。</span></span>", "answer": "However often you call, the line is always busy. / No matter how often you call, the line is always busy.", "explain": "<span class=\"enx\">However often = every time, without exception.</span><span class=\"zh\" lang=\"zh-Hans\">However often＝每一次，没有例外。</span>"}, "gym:concession:10": {"id": "gym:concession:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Although I respect his experience, I think he is wrong this time. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Much as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Much as 开头。</span></span>", "answer": "Much as I respect his experience, I think he is wrong this time.", "explain": "<span class=\"enx\">Polite disagreement at work: grant the point, then disagree.</span><span class=\"zh\" lang=\"zh-Hans\">工作中的礼貌反对：先承认，再反对。</span>"}, "gym:concession:11": {"id": "gym:concession:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Even though the town is small, it has three good schools. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Small as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Small as 开头。</span></span>", "answer": "Small as the town is, it has three good schools. / Small as it is, the town has three good schools.", "explain": "<span class=\"enx\">The present tense is fine: Small as the town is.</span><span class=\"zh\" lang=\"zh-Hans\">现在时没问题：Small as the town is。</span>"}, "gym:concession:12": {"id": "gym:concession:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "It doesn&#x27;t matter how carefully you plan; something goes wrong on moving day. <span class=\"muted\">→ <span class=\"enx\">Start with <i>However carefully</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 However carefully 开头。</span></span>", "answer": "However carefully you plan, something goes wrong on moving day. / No matter how carefully you plan, something goes wrong on moving day.", "explain": "<span class=\"enx\">The adverb carefully stays right after however.</span><span class=\"zh\" lang=\"zh-Hans\">副词 carefully 紧跟 however。</span>"}, "gym:concession:13": {"id": "gym:concession:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Although it sounds simple, the form takes an hour. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Simple as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Simple as 开头。</span></span>", "answer": "Simple as it sounds, the form takes an hour. / Simple as it may sound, the form takes an hour.", "explain": "<span class=\"enx\">may sound adds a little more doubt.</span><span class=\"zh\" lang=\"zh-Hans\">may sound 多一点怀疑。</span>"}, "gym:concession:14": {"id": "gym:concession:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "Although I would love to stay, I have an early start. <span class=\"muted\">→ <span class=\"enx\">Start with <i>Much as</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 Much as 开头。</span></span>", "answer": "Much as I would love to stay, I have an early start. / Much as I'd love to stay, I have an early start.", "explain": "<span class=\"enx\">The classic polite way to leave a party.</span><span class=\"zh\" lang=\"zh-Hans\">离开聚会时经典的客气说法。</span>"}, "gym:concession:15": {"id": "gym:concession:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Concession: however much, much as, tired as she was", "q": "It doesn&#x27;t matter how many times we explain the rule; some drivers ignore it. <span class=\"muted\">→ <span class=\"enx\">Start with <i>However many times</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 However many times 开头。</span></span>", "answer": "However many times we explain the rule, some drivers ignore it. / No matter how many times we explain the rule, some drivers ignore it.", "explain": "<span class=\"enx\">However many + plural noun; however much + uncountable.</span><span class=\"zh\" lang=\"zh-Hans\">However many + 复数名词；however much + 不可数名词。</span>"}, "gym:passive-reporting:1": {"id": "gym:passive-reporting:1", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "People say that the old mill is haunted. <span class=\"muted\">→ <span class=\"enx\">Use <i>It is said that</i> or <i>is said to</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 It is said that 或 is said to。</span></span>", "answer": "It is said that the old mill is haunted. / The old mill is said to be haunted.", "explain": "<span class=\"enx\">Two shapes: It is said that + clause, or subject + is said to + verb.</span><span class=\"zh\" lang=\"zh-Hans\">两种写法：It is said that + 从句，或 主语 + is said to + 动词。</span>"}, "gym:passive-reporting:2": {"id": "gym:passive-reporting:2", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "Experts believe that the new rule will reduce waiting times. <span class=\"muted\">→ <span class=\"enx\">Start with <i>It is believed</i>.</span><span class=\"zh\" lang=\"zh-Hans\">以 It is believed 开头。</span></span>", "answer": "It is believed that the new rule will reduce waiting times.", "explain": "<span class=\"enx\">The experts disappear; the belief stays.</span><span class=\"zh\" lang=\"zh-Hans\">专家不见了，看法还在。</span>"}, "gym:passive-reporting:3": {"id": "gym:passive-reporting:3", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "Reports say that the fire started in the kitchen. <span class=\"muted\">→ <span class=\"enx\">Use <i>is reported to have</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is reported to have。</span></span>", "answer": "The fire is reported to have started in the kitchen. / It is reported that the fire started in the kitchen. / It has been reported that the fire started in the kitchen.", "explain": "<span class=\"enx\">Earlier event: to have started.</span><span class=\"zh\" lang=\"zh-Hans\">更早的事：to have started。</span>"}, "gym:passive-reporting:4": {"id": "gym:passive-reporting:4", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "People think the bridge was built in the 1880s. <span class=\"muted\">→ <span class=\"enx\">Use <i>is thought to have been</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is thought to have been。</span></span>", "answer": "The bridge is thought to have been built in the 1880s. / It is thought that the bridge was built in the 1880s.", "explain": "<span class=\"enx\">Past and passive together: to have been built.</span><span class=\"zh\" lang=\"zh-Hans\">过去加被动：to have been built。</span>"}, "gym:passive-reporting:5": {"id": "gym:passive-reporting:5", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "Everyone knows that the road floods every spring. <span class=\"muted\">→ <span class=\"enx\">Use <i>It is known that</i> or <i>is known to</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 It is known that 或 is known to。</span></span>", "answer": "It is known that the road floods every spring. / It is well known that the road floods every spring. / The road is known to flood every spring.", "explain": "<span class=\"enx\">is known to + base verb for a regular fact.</span><span class=\"zh\" lang=\"zh-Hans\">is known to + 动词原形，表示规律性的事实。</span>"}, "gym:passive-reporting:6": {"id": "gym:passive-reporting:6", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "Many people consider the night market the best in the city. <span class=\"muted\">→ <span class=\"enx\">Use <i>is considered</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is considered。</span></span>", "answer": "The night market is considered the best in the city. / The night market is considered to be the best in the city. / The night market is widely considered the best in the city.", "explain": "<span class=\"enx\">to be is optional after considered.</span><span class=\"zh\" lang=\"zh-Hans\">considered 之后的 to be 可省。</span>"}, "gym:passive-reporting:7": {"id": "gym:passive-reporting:7", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "People say the owner sold the shop last year. <span class=\"muted\">→ <span class=\"enx\">Use <i>is said to have</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is said to have。</span></span>", "answer": "The owner is said to have sold the shop last year. / It is said that the owner sold the shop last year.", "explain": "<span class=\"enx\">The selling is earlier than the saying, so to have sold.</span><span class=\"zh\" lang=\"zh-Hans\">卖店早于「说」，所以用 to have sold。</span>"}, "gym:passive-reporting:8": {"id": "gym:passive-reporting:8", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "Officials expect the line to open in the spring. <span class=\"muted\">→ <span class=\"enx\">Use <i>is expected to</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is expected to。</span></span>", "answer": "The line is expected to open in the spring. / It is expected that the line will open in the spring.", "explain": "<span class=\"enx\">Future event, so to open, or will open after that.</span><span class=\"zh\" lang=\"zh-Hans\">将来的事：to open，或 that 之后用 will open。</span>"}, "gym:passive-reporting:9": {"id": "gym:passive-reporting:9", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "People believe that the painting was lost in a fire. <span class=\"muted\">→ <span class=\"enx\">Use <i>is believed to have been</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is believed to have been。</span></span>", "answer": "The painting is believed to have been lost in a fire. / It is believed that the painting was lost in a fire.", "explain": "<span class=\"enx\">Passive in the past: to have been lost.</span><span class=\"zh\" lang=\"zh-Hans\">过去的被动：to have been lost。</span>"}, "gym:passive-reporting:10": {"id": "gym:passive-reporting:10", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "Some people claim that the diet cures back pain. <span class=\"muted\">→ <span class=\"enx\">Use <i>It is claimed that</i> or <i>is claimed to</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 It is claimed that 或 is claimed to。</span></span>", "answer": "It is claimed that the diet cures back pain. / The diet is claimed to cure back pain.", "explain": "<span class=\"enx\">claimed signals doubt; a good choice for health claims you have not checked.</span><span class=\"zh\" lang=\"zh-Hans\">claimed 暗示存疑，适合转述没核实过的健康说法。</span>"}, "gym:passive-reporting:11": {"id": "gym:passive-reporting:11", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "People think that she is living abroad now. <span class=\"muted\">→ <span class=\"enx\">Use <i>is thought to be</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is thought to be。</span></span>", "answer": "She is thought to be living abroad now. / It is thought that she is living abroad now.", "explain": "<span class=\"enx\">Ongoing situation: to be living.</span><span class=\"zh\" lang=\"zh-Hans\">正在进行的状态：to be living。</span>"}, "gym:passive-reporting:12": {"id": "gym:passive-reporting:12", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "Researchers estimate that most households own more than one screen. <span class=\"muted\">→ <span class=\"enx\">Use <i>It is estimated that</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 It is estimated that。</span></span>", "answer": "It is estimated that most households own more than one screen. / Most households are estimated to own more than one screen.", "explain": "<span class=\"enx\">Estimate is the usual verb for a rough number.</span><span class=\"zh\" lang=\"zh-Hans\">估计大致数字时常用 estimate。</span>"}, "gym:passive-reporting:13": {"id": "gym:passive-reporting:13", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "People once believed that cold weather caused colds. <span class=\"muted\">→ <span class=\"enx\">Use <i>It was once believed that</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 It was once believed that。</span></span>", "answer": "It was once believed that cold weather caused colds. / Cold weather was once believed to cause colds.", "explain": "<span class=\"enx\">Past belief, so It was.</span><span class=\"zh\" lang=\"zh-Hans\">过去的看法，用 It was。</span>"}, "gym:passive-reporting:14": {"id": "gym:passive-reporting:14", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "People report that the company is moving its head office. <span class=\"muted\">→ <span class=\"enx\">Use <i>is reported to be</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is reported to be。</span></span>", "answer": "The company is reported to be moving its head office. / It is reported that the company is moving its head office.", "explain": "<span class=\"enx\">In progress now: to be moving.</span><span class=\"zh\" lang=\"zh-Hans\">正在进行：to be moving。</span>"}, "gym:passive-reporting:15": {"id": "gym:passive-reporting:15", "type": "rewrite", "unit": "tool:gym", "unitTitle": "Sentence gym · Passive reporting: It is said that..., is thought to have...", "q": "Locals say the lake is the deepest in the province. <span class=\"muted\">→ <span class=\"enx\">Use <i>is said to be</i>.</span><span class=\"zh\" lang=\"zh-Hans\">用 is said to be。</span></span>", "answer": "The lake is said to be the deepest in the province. / It is said that the lake is the deepest in the province.", "explain": "<span class=\"enx\">The classic line in travel writing.</span><span class=\"zh\" lang=\"zh-Hans\">旅游文章里的经典句式。</span>"}});